insert into accounting.card_transactions (
  company_id, import_file_id, source_system, used_date, merchant_name, amount,
  payment_date, source_record_id, source_row_hash, raw_data
)
select
  c.id,
  f.id,
  'smbc_card_csv',
  src.used_date::date,
  src.merchant_name,
  src.amount::numeric,
  src.payment_date::date,
  src.source_record_id,
  src.source_row_hash,
  src.raw_data
from c
join src on true
join accounting.import_files f
  on f.company_id=c.id
 and f.source_system='smbc_card_csv'
 and f.sha256=src.file_sha
on conflict (company_id, source_system, source_row_hash) do nothing;

-- 3) Import signed bank rows: inflow positive, outflow negative.
with c as (
  select id
  from accounting.companies
  where id = '3cb6f6ef-3c74-47d9-8266-2ceafcdb2b73'
),
src(file_sha,transaction_date,amount,description,balance,source_record_id,source_row_hash,raw_data) as (
  values
