insert into accounting.bank_transactions (
  company_id, import_file_id, source_system, transaction_date, amount,
  description, balance, source_record_id, source_row_hash, raw_data
)
select
  c.id,
  f.id,
  'gmo_aozora_bank_csv',
  src.transaction_date::date,
  src.amount::numeric,
  src.description,
  src.balance::numeric,
  src.source_record_id,
  src.source_row_hash,
  src.raw_data
from c
join src on true
join accounting.import_files f
  on f.company_id=c.id
 and f.source_system='gmo_aozora_bank_csv'
 and f.sha256=src.file_sha
on conflict (company_id, source_system, source_row_hash) do nothing;

-- 4) Conservative card auto-match, pass A:
-- same used date + amount, with exactly one unmatched card row and one unmatched
-- FY2025 journal containing a SMBC-card line for that date+amount.
with fy as (
  select id
  from accounting.fiscal_years
  where company_id='3cb6f6ef-3c74-47d9-8266-2ceafcdb2b73'
    and name='2025年度'
  limit 1
),
card_journal as (
  select j.id as journal_id, j.entry_date, jl.amount
  from accounting.journals j
  join fy on fy.id=j.fiscal_year_id
  join accounting.journal_lines jl on jl.journal_id=j.id
  join accounting.accounts a on a.id=jl.account_id
  left join accounting.sub_accounts sa on sa.id=jl.sub_account_id
  where j.source_system='moneyforward'
    and a.name='未払金'
    and sa.source_record_id in (
      'bX0I01uviL7IBJGF1bjYdQ%3D%3D',
      'eOCEMUAA%2FLJUda99tgjCSQ%3D%3D'
    )
    and jl.side='credit'
),
ct as (
  select id, used_date, amount
  from accounting.card_transactions
  where company_id='3cb6f6ef-3c74-47d9-8266-2ceafcdb2b73'
    and source_system='smbc_card_csv'
    and used_date between date '2025-11-01' and date '2026-10-31'
    and matched_journal_id is null
),
groups as (
  select
    ct.used_date,
    ct.amount,
    count(distinct ct.id) as card_count,
    count(distinct cj.journal_id) as journal_count
  from ct
  join card_journal cj
    on cj.entry_date=ct.used_date
   and cj.amount=ct.amount
  group by ct.used_date, ct.amount
  having count(distinct ct.id)=1
     and count(distinct cj.journal_id)=1
),
chosen as (
  select ct.id as card_id, cj.journal_id
  from groups g
  join ct
    on ct.used_date=g.used_date and ct.amount=g.amount
  join card_journal cj
    on cj.entry_date=g.used_date and cj.amount=g.amount
)
update accounting.card_transactions c
set matched_journal_id=chosen.journal_id
from chosen
where c.id=chosen.card_id
  and c.matched_journal_id is null;

-- 5) Conservative bank auto-match:
-- signed amount must equal the bank-side journal line:
-- debit to bank = positive inflow, credit to bank = negative outflow.
with fy as (
  select id
  from accounting.fiscal_years
  where company_id='3cb6f6ef-3c74-47d9-8266-2ceafcdb2b73'
    and name='2025年度'
  limit 1
),
bank_journal as (
  select
    j.id as journal_id,
    j.entry_date,
    case when jl.side='debit' then jl.amount else -jl.amount end as signed_amount
  from accounting.journals j
  join fy on fy.id=j.fiscal_year_id
  join accounting.journal_lines jl on jl.journal_id=j.id
  join accounting.accounts a on a.id=jl.account_id
  left join accounting.sub_accounts sa on sa.id=jl.sub_account_id
  where j.source_system='moneyforward'
    and a.name='普通預金'
    and sa.source_record_id='xQwY1B2EXE%2BJKn0HassIcg%3D%3D'
),
bt as (
  select id, transaction_date, amount
  from accounting.bank_transactions
  where company_id='3cb6f6ef-3c74-47d9-8266-2ceafcdb2b73'
    and source_system='gmo_aozora_bank_csv'
    and transaction_date between date '2025-11-01' and date '2026-10-31'
    and matched_journal_id is null
),
groups as (
  select
    bt.transaction_date,
    bt.amount,
    count(distinct bt.id) as bank_count,
    count(distinct bj.journal_id) as journal_count
  from bt
  join bank_journal bj
    on bj.entry_date=bt.transaction_date
   and bj.signed_amount=bt.amount
  group by bt.transaction_date, bt.amount
  having count(distinct bt.id)=1
     and count(distinct bj.journal_id)=1
),
chosen as (
  select bt.id as bank_id, bj.journal_id
  from groups g
  join bt
    on bt.transaction_date=g.transaction_date and bt.amount=g.amount
  join bank_journal bj
    on bj.entry_date=g.transaction_date and bj.signed_amount=g.amount
)
update accounting.bank_transactions b
set matched_journal_id=chosen.journal_id
from chosen
where b.id=chosen.bank_id
  and b.matched_journal_id is null;

-- 6) Import-count validation (matching counts are intentionally not forced).
do $$
declare
  v_card integer;
  v_card_fy integer;
  v_bank integer;
  v_files integer;
begin
  select count(*) into v_card
  from accounting.card_transactions
  where company_id='3cb6f6ef-3c74-47d9-8266-2ceafcdb2b73'
    and source_system='smbc_card_csv';

  select count(*) into v_card_fy
  from accounting.card_transactions
  where company_id='3cb6f6ef-3c74-47d9-8266-2ceafcdb2b73'
    and source_system='smbc_card_csv'
    and used_date between date '2025-11-01' and date '2026-10-31';

  select count(*) into v_bank
  from accounting.bank_transactions
  where company_id='3cb6f6ef-3c74-47d9-8266-2ceafcdb2b73'
    and source_system='gmo_aozora_bank_csv';

  select count(*) into v_files
  from accounting.import_files
  where company_id='3cb6f6ef-3c74-47d9-8266-2ceafcdb2b73'
    and source_system in ('smbc_card_csv','gmo_aozora_bank_csv');

  if v_card <> 358 then
    raise exception 'Expected 358 imported card rows, got %', v_card;
  end if;
  if v_card_fy <> 318 then
    raise exception 'Expected 318 FY2025 card rows, got %', v_card_fy;
  end if;
  if v_bank <> 30 then
    raise exception 'Expected 30 bank rows, got %', v_bank;
  end if;
  if v_files <> 13 then
    raise exception 'Expected 13 import_files rows, got %', v_files;
  end if;
end
$$;

commit;
